import{z as i,x as n,o as t,c as d,q as o,j as l,D as r,d as e,s,S as A,b as a}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"读写锁","description":"","frontmatter":{"title":"读写锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rwlock.md","filePath":"cs/rwlock.md","lastUpdated":1791413859000}'),c={name:"cs/rwlock.md"};function p(m,E,D,u,h,C){const B=n("Mermaid");return t(),d("div",null,[E[2]||(E[2]=o('<h1 id="读写锁" tabindex="-1">读写锁 <a class="header-anchor" href="#读写锁" aria-label="Permalink to &quot;读写锁&quot;">​</a></h1><div class="epigraph"><p>读者与读者可以重叠；写者与任何人互斥。读多写少时它比一把 mutex 更松，写者却可能被源源不断的读者挡住。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Love, LKD 整理</footer></div><p><a href="/cs/futex">上一课</a>让互斥可以很便宜。许多内核结构（路由表、挂载表）读远多于写：读者彼此不破坏不变量。缺口是 <strong>rwlock</strong>：共享读、排他写。本课钉语义与写者饥饿，不把 seqlock、RCU 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>mutex 把读者也串行化，吞吐被锁字卡住。<a href="/cs/race-critical">临界区</a> 的不变量若只被写者打破，读者重叠是安全的。实现：计数「当前读者」或用状态字的读计数+写标志，获取时原子更新。写者等到计数为零。缺口不是 futex 的 wait 机制（可以建在它或自旋上），而是这套<strong>兼容性矩阵</strong>。</p><p><span class="marginnote">写者饥饿：读者不断进场，计数永不归零。对策是写者到达后阻挡新读者，或改用 seqlock/RCU。</span></p><p><span class="marginnote">「兼容性矩阵」就是用一张「谁和谁能同时进临界区」的对照表来定义锁的语义：读×读打勾、读×写和写×写打叉。锁的获取与释放逻辑都是从这张表倒推出来的。</span></p><p><span class="marginnote">可以把它想象成电梯：读者是多人共乘的普通电梯，写者是货梯——货梯运行期间整部电梯归它专用。乘客一多，货梯就永远排不上队，这正是下面要说的饥饿问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>read_lock</code>：若无写者则读者计数加一。<code>write_lock</code>：等无读者无写者。IRQ 版同样要标明能否在硬中断里读。睡眠版 rwsem：等待者可睡，规则同 mutex——禁止 IRQ。公平策略：写者等待时新读者是否允许，本课要求说清楚，默认承认存在饥饿模式。</p>',10)),(t(),l(A,null,{default:r(()=>[s(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E8%AF%BB%E8%80%85%22%5D%20--%3E%20OK%5B%22%E5%8F%AF%E9%87%8D%E5%8F%A0%22%5D%0A%20%20R2%5B%22%E8%AF%BB%E8%80%85%22%5D%20--%3E%20OK%0A%20%20W%5B%22%E5%86%99%E8%80%85%22%5D%20--%3E%20EX%5B%22%E4%B8%8E%E6%89%80%E6%9C%89%E4%BA%BA%E4%BA%92%E6%96%A5%22%5D%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"升级（持读再要写）易死锁：另一读者同样升级。主干禁止隐式升级。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("rwlock 提高读侧并行，写侧延迟变差。与"),a("a",{href:"/cs/scheduling-metrics"},"调度"),e("：一长串读者会把写者的等待做成饥饿，公平尺子坏掉。缓存上，读计数仍是共享行，读者多时也会乒乓——这把后课 seqlock（读侧几乎不写共享行）和 RCU 的动机钉住。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：读锁字是 64 字节缓存行上的一个计数器。读者从 1 个涨到 32 个并发时，这个计数器要被 32 个核来回改写——每个读者进入和退出各写一次，就是 64 次跨核无效化。「读不写数据」不等于「不写锁字」。")],-1)),(t(),l(A,null,{default:r(()=>[s(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E8%80%85%E8%AF%B7%E6%B1%82%E5%86%99%E9%94%81%22%5D%20--%3E%20Q%7B%22%E6%AD%A4%E5%88%BB%E6%9C%89%E6%97%A0%E8%AF%BB%E8%80%85%E6%88%96%E5%86%99%E8%80%85%3F%22%7D%0A%20%20Q%20--%20%22%E8%AE%A1%E6%95%B0%E4%B8%BA%E9%9B%B6%22%20--%3E%20AC%5B%22%E7%AB%8B%E5%8D%B3%E8%8E%B7%E5%BE%97%E5%86%99%E9%94%81%22%5D%0A%20%20Q%20--%20%22%E4%BB%8D%E6%9C%89%E8%AF%BB%E8%80%85%22%20--%3E%20WAIT%5B%22%E5%86%99%E8%80%85%E6%8C%82%E8%B5%B7%E7%AD%89%E5%BE%85%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E8%AF%BB%E8%80%85%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20FAIR%7B%22%E5%86%99%E8%80%85%E6%98%AF%E5%90%A6%E5%B7%B2%E5%9C%A8%E7%AD%89%E5%BE%85%3F%22%7D%0A%20%20FAIR%20--%20%22%E5%81%8F%E8%A2%92%E8%AF%BB%E8%80%85%E7%AD%96%E7%95%A5%22%20--%3E%20IN%5B%22%E6%94%BE%E8%A1%8C%2C%20%E8%AE%A1%E6%95%B0%E5%8A%A0%E4%B8%80%22%5D%0A%20%20IN%20--%3E%20MORE%5B%22%E8%AF%BB%E8%80%85%E6%B5%81%E6%8C%81%E7%BB%AD%2C%20%E8%AE%A1%E6%95%B0%E9%9A%BE%E5%BD%92%E9%9B%B6%22%5D%0A%20%20MORE%20--%3E%20STARVE%5B%22%E5%86%99%E8%80%85%E8%A2%AB%E9%A5%BF%E6%AD%BB%22%5D%0A%20%20FAIR%20--%20%22%E5%86%99%E8%80%85%E4%BC%98%E5%85%88%E7%AD%96%E7%95%A5%22%20--%3E%20BLOCK%5B%22%E9%98%BB%E6%8C%A1%E6%96%B0%E8%AF%BB%E8%80%85%22%5D%0A%20%20BLOCK%20--%3E%20DRAIN%5B%22%E5%AD%98%E9%87%8F%E8%AF%BB%E8%80%85%E9%80%80%E5%87%BA%2C%20%E8%AE%A1%E6%95%B0%E5%BD%92%E9%9B%B6%22%5D%0A%20%20DRAIN%20--%3E%20AC%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=o('<p>这张图回答的问题是：写者到底卡在哪一步。饥饿不是「写者运气差」，而是「新读者持续放行」这条边在偏袒读者的策略下永远通畅；把这条边改成 BLOCK，等待才有了终点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Linux <code>rwlock_t</code> 与 <code>rw_semaphore</code> 的全部 API 对照完。也不把数据库里的意向锁混进来。seqlock 用版本号让读者无锁重试，下一课。</p><p>后课默认：读可重叠、写排他，写者可能饿。读侧几乎不写锁字的版本号方案，下一课 seqlock。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rwlock：读者共享、写者排他；写者可被读者流饿死。</li><li>不可随意读升级为写。</li><li>版本号无锁读是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>。</li></ul>',6))])}const _=i(c,[["render",p]]);export{k as __pageData,_ as default};
